#include <iostream>
#include <utility>
using namespace std;

const long long MOD = 1000000007LL;

// returns (F(k), F(k+1)) modulo MOD
pair<long long, long long> fibPair(long long k) {
    if (k == 0) return {0, 1};
    auto [a, b] = fibPair(k >> 1);
    long long t = (2 * b - a + MOD) % MOD;
    long long c = a * t % MOD;
    long long d = (a * a + b * b) % MOD;
    if (k & 1) return {d, (c + d) % MOD};
    return {c, d};
}

int main() {
    long long n;
    cin >> n;
    cout << fibPair(n).first << endl;
    return 0;
}

code.java:
import java.util.Scanner;

public class Main {
    static final long MOD = 1_000_000_007L;

    // returns {F(k), F(k+1)} modulo MOD
    static long[] fibPair(long k) {
        if (k == 0) return new long[] {0, 1};
        long[] half = fibPair(k >> 1);
        long a = half[0], b = half[1];
        long c = a * ((2 * b - a + MOD) % MOD) % MOD;
        long d = (a * a + b * b) % MOD;
        if ((k & 1) == 1) return new long[] {d, (c + d) % MOD};
        return new long[] {c, d};
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        System.out.println(fibPair(n)[0]);
    }
}
